import pathlib,sys,json,hashlib,html
ROOT=pathlib.Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'.network-runtime/topic-libs'))
import numpy as np
from sklearn.feature_extraction.text import CountVectorizer
from sklearn.metrics.pairwise import cosine_similarity
from scipy.cluster.hierarchy import linkage,leaves_list
from scipy.spatial.distance import squareform

def main():
 for kind,title,inputname in [('place-space','地点＋空间词','place-space-topic-input.json'),('allword','全书各类词汇','allword-topic-input.json')]:
  src=json.load(open(ROOT/'.network-runtime'/inputname,encoding='utf8'));assert src['source_sha256']==hashlib.sha256((ROOT/'data-package.json').read_bytes()).hexdigest()
  cs=src['chapters'];valid=[i for i,c in enumerate(cs)if c['tokens']];missing=[i for i,c in enumerate(cs)if not c['tokens']]
  x=CountVectorizer(analyzer=lambda d:d).fit_transform([cs[i]['tokens']for i in valid]);a=cosine_similarity(x);dist=np.clip(1-a,0,1);np.fill_diagonal(dist,0);order=[valid[int(i)]for i in leaves_list(linkage(squareform(dist,checks=False),method='average'))]+missing
  mat=np.full((len(cs),len(cs)),np.nan);mat[np.ix_(valid,valid)]=a
  out={'source_sha256':src['source_sha256'],'kind':kind,'method':'Raw term-frequency cosine; no TF-IDF; average linkage of 1-cosine. Original token forms, explicit stopwords excluded. Null for empty documents.','chapters':[{'id':c['id'],'title':c['title'],'token_count':len(c['tokens'])}for c in cs],'order':order,'similarity':[[None if np.isnan(v)else round(float(v),8)for v in row]for row in mat]}
  (ROOT/f'reports/{kind}-raw-frequency-interactive.json').write_text(json.dumps(out,ensure_ascii=False),encoding='utf8')
  page='''<!doctype html><meta charset="utf-8"><title>TITLE相似度</title><style>body{font:16px/1.6 system-ui;background:#faf9f5;margin:28px;color:#25333d}canvas{max-width:100%;border:1px solid #ddd;background:white;image-rendering:pixelated}select,input{padding:8px;margin:6px}table{border-collapse:collapse;width:100%}td,th{padding:7px;text-align:left;border-bottom:1px solid #ddd}#tip{min-height:55px}#bar{height:12px;width:250px;background:linear-gradient(to right,rgb(250,250,245),rgb(30,110,175))}</style><h1>TITLE相似度</h1><p>原始词频余弦相似度，不作TF-IDF加权。横纵轴均为全书篇目，经层次聚类排序，不显示轴标签。悬停看两篇，点击选择比较。</p><div id="bar"></div><small>0：低　→　1：高；灰色：缺少有效词项</small><p>CAPTION</p><canvas id="heat" width="982" height="982" style="width:900px"></canvas><p id="tip">在格子上移动鼠标查看篇名和分数。</p><input id="search" placeholder="搜索篇名"><select id="chapter"></select><p id="info"></p><table><thead><tr><th>相似篇目</th><th>相似度</th></tr></thead><tbody id="rows"></tbody></table><p>对角线是自身相似度。短篇词少时高分需谨慎；同义词未合并。全词版保留各类词汇，排除标点和既有停用词，未重新分词。</p><script>const D=PAYLOAD;const $=id=>document.getElementById(id),canvas=$('heat'),ctx=canvas.getContext('2d'),n=D.chapters.length;let selected=0;for(let i=0;i<n;i++)for(let j=0;j<n;j++){const v=D.similarity[D.order[i]][D.order[j]];ctx.fillStyle=v===null?'#ccc':`rgb(${Math.round(250-220*v)},${Math.round(250-140*v)},${Math.round(245-70*v)})`;ctx.fillRect(j*2,i*2,2,2)}
function cell(e){const r=canvas.getBoundingClientRect();return [Math.floor((e.clientY-r.top)*n/r.height),Math.floor((e.clientX-r.left)*n/r.width)]}canvas.onmousemove=e=>{const[i,j]=cell(e);if(i<0||j<0||i>=n||j>=n)return;const a=D.order[i],b=D.order[j],v=D.similarity[a][b];$('tip').textContent=`《${D.chapters[a].title}》／《${D.chapters[b].title}》：${v===null?'缺少有效词项':v.toFixed(4)}`};canvas.onclick=e=>{const[i]=cell(e);if(i<0||i>=n)return;selected=D.order[i];$('search').value='';options()};
function show(){const c=D.chapters[selected];$('info').textContent=`《${c.title}》：${c.token_count}个有效词次`;$('rows').replaceChildren();const neighbors=D.similarity[selected].map((v,i)=>({v,i})).filter(x=>x.i!==selected&&x.v!==null).sort((a,b)=>b.v-a.v||a.i-b.i).slice(0,15);for(const x of neighbors){const tr=document.createElement('tr');for(const value of [D.chapters[x.i].title,x.v.toFixed(4)]){const td=document.createElement('td');td.textContent=value;tr.append(td)}tr.onclick=()=>{selected=x.i;$('search').value='';options()};$('rows').append(tr)}}
function options(){const q=$('search').value.trim();$('chapter').replaceChildren();D.chapters.forEach((c,i)=>{if(!c.title.includes(q))return;const o=document.createElement('option');o.value=i;o.textContent=c.title;$('chapter').append(o)});if([...$('chapter').options].some(o=>Number(o.value)===selected))$('chapter').value=selected;else if($('chapter').options.length)selected=Number($('chapter').value);show()}$('search').oninput=options;$('chapter').onchange=()=>{selected=Number($('chapter').value);show()};options();</script>'''
  page=page.replace('TITLE',title).replace('CAPTION',f'共{len(cs)}篇；{len(valid)}篇有有效词项，{len(missing)}篇标灰。').replace('PAYLOAD',json.dumps(out,ensure_ascii=False).replace('<','\\u003c'))
  (ROOT/f'reports/{kind}-詞頻相似度互動圖.html').write_text(page,encoding='utf8');print(kind,len(valid),x.shape)
if __name__=='__main__':main()
